221:         char16_t next_ch = *(pos + 1);
222:         if (next_ch == '/') {
223:           lineComment();
224:           // dont update lastToken
225:           continue;
226:         }
227:         else if (next_ch == '*') {
228:           blockComment(true);
229:           // dont update lastToken
230:           continue;
231:         }
232:         // fallthrough
233:       }
234:       default:
235:         // as soon as we hit a non-module token, we go to main parser
236:         facade = false;
237:         pos--;
238:         goto mainparse; // oh yeahhh
239:     }
240:     lastTokenPos = pos;
241:   }
242: 
243:   if (has_error)
244:     return false;
245: 
246:   // the minimal build has no facade fast-path; everything goes through mainparse
247:   mainparse:
248: #endif
249:   while (pos++ < end) {
250:     ch = *pos;
251: 
252:     if (ch == 32 || ch < 14 && ch > 8)
253:       continue;
254: 
255:     if (!consumeToken(ch))
256:       return false;
257:   }
258: 
259:   if (openTokenDepth || has_error || dynamicImportStackDepth)
260:     return false;
261: 
262:   // succeess
263:   return true;
264: }
