266: void tryParseImportStatement () {
267:   char16_t* startPos = pos;
268: 
269:   pos += 6;
270: 
271:   char16_t ch = commentWhitespace(true);
272: 
273:   char16_t* maybePhasePos = pos;
274: 
275:   int phase_keyword = 0;
276: 
277:   if (ch == '.') {
278:     // import.meta
279:     pos++;
280:     ch = commentWhitespace(true);
281:     // import.meta indicated by d == -2
282:     if (ch == 'm' && memcmp(pos + 1, &ETA[0], 3 * 2) == 0 && (isSpread(lastTokenPos) || *lastTokenPos != '.')) {
283:       addImport(startPos, startPos, pos + 4, IMPORT_META);
284:       return;
285:     }
286:     else if (ch == 's' && memcmp(pos + 1, &OURCE[0], 5 * 2) == 0 && (isSpread(lastTokenPos) || *lastTokenPos != '.')) {
287:       phase_keyword = 1;
288:       pos += 6;
289:       ch = commentWhitespace(true);
290:     }
291:     else if (ch == 'd' && memcmp(pos + 1, &EFER[0], 4 * 2) == 0 && (isSpread(lastTokenPos) || *lastTokenPos != '.')) {
292:       phase_keyword = 2;
293:       pos += 5;
294:       ch = commentWhitespace(true);
295:     }
296:     else {
297:       return;
298:     }
299:   }
300:   else if (pos > startPos + 6 && ch == 's' && memcmp(pos + 1, &OURCE[0], 5 * 2) == 0 && isBrOrWs(*(pos + 6))) {
301:     phase_keyword = 1;
302:     pos += 6;
303:     ch = commentWhitespace(true);
304:     // need a space after the source keyword, and must not be followed by from keyword
305:     if (pos == maybePhasePos + 6 || ch == 'f' && memcmp(pos + 1, &ROM[0], 3 * 2) == 0 && isBrOrWsOrPunctuatorNotDot(*(pos + 4))) {
306:       pos = maybePhasePos;
307:       phase_keyword = 0;
308:     }
309:   }
310:   else if (pos > startPos + 5 && ch == 'd' && memcmp(pos + 1, &EFER[0], 4 * 2) == 0 && isBrOrWs(*(pos + 5))) {
311:     phase_keyword = 2;
312:     pos += 5;
313:     ch = commentWhitespace(true);
314:     // need a * after the defer keyword
315:     if (ch != '*') {
316:       pos = maybePhasePos;
317:       phase_keyword = 0;
318:     }
319:   }
320: 
321:   // dynamic import
322:   if (ch == '(') {
323:     openTokenStack[openTokenDepth].token = ImportParen;
324:     openTokenStack[openTokenDepth++].pos = pos;
325:     if (*lastTokenPos == '.')
326:       return;
327:     // dynamic import indicated by positive d
328:     char16_t* dynamicPos = pos;
329:     // try parse a string, to record a safe dynamic import string
330:     pos++;
331:     ch = commentWhitespace(true);
332:     addImport(startPos, pos, 0, dynamicPos);
333:     if (phase_keyword > 0)
334:       import_write_head->import_ty = phase_keyword == 1 ? DynamicSourcePhase : DynamicDeferPhase;
335:     dynamicImportStack[dynamicImportStackDepth++] = import_write_head;
336:     if (ch == '\'') {
337:       stringLiteral(ch);
338:     }
339:     else if (ch == '"') {
340:       stringLiteral(ch);
341:     }
342:     else if (ch == '`' && noSubstitutionTemplate()) {
343:       // A no-substitution template literal is a constant string, so it is a
344:       // safe specifier exactly like a quoted one. An interpolated template
345:       // leaves noSubstitutionTemplate() false and falls through to the open-
346:       // token machinery, which records the import as unsafe (n stays unset).
347:     }
348:     else {
349:       pos--;
350:       return;
351:     }
352:     pos++;
353:     char16_t* endPos = pos;
354:     ch = commentWhitespace(true);
355:     if (ch == ',') {
356:       pos++;
357:       ch = commentWhitespace(true);
358:       import_write_head->end = endPos;
359:       import_write_head->attr_index = pos;
360:       import_write_head->safe = true;
361:       pos--;
362:     }
363:     else if (ch == ')') {
364:       openTokenDepth--;
365:       import_write_head->end = endPos;
366:       import_write_head->statement_end = pos + 1;
367:       import_write_head->safe = true;
368:       dynamicImportStackDepth--;
369:     }
370:     else {
371:       pos--;
372:     }
373:     return;
374:   }
375: 
376:   if (ch == '{' && phase_keyword == 0) {
377:     // import statement only permitted at base-level
378:     if (openTokenDepth != 0) {
379:       pos--;
380:       return;
381:     }
382: 
383:     while (pos < end) {
384:       ch = commentWhitespace(true);
385:       if (isQuote(ch)) {
386:         stringLiteral(ch);
387:       } else if (ch == '}') {
388:         pos++;
389:         break;
390:       }
391:       pos++;
392:     }
393: 
394:     ch = commentWhitespace(true);
395:     if (ch == 'f' && memcmp(pos + 1, &ROM[0], 3 * 2) != 0) {
396:       syntaxError();
397:       return;
398:     }
399: 
400:     pos += 4;
401:     ch = commentWhitespace(true);
402: 
403:     if (!isQuote(ch)) {
404:       return syntaxError();
405:     }
406: 
407:     readImportString(startPos, ch, false);
408:   }
409:   else {
410:     if (!(ch == '"' || ch == '\'' || ch == '*')) {
411:       // no space after "import" -> not an import keyword
412:       if (pos == startPos + 6) {
413:         pos--;
414:         return;
415:       }
416:     }
417:     // import defer * as foo mandates *;
418:     // import statement only permitted at base-level
419:     if (phase_keyword == 2 && ch != '*' || openTokenDepth != 0) {
420:       pos--;
421:       return;
422:     }
423:     while (pos < end) {
424:       ch = *pos;
425:       if (isQuote(ch)) {
426:         readImportString(startPos, ch, phase_keyword);
427:         return;
428:       }
429:       pos++;
430:     }
431:     syntaxError();
432:   }
433: }
