435: // True for a char that can end a value. skipExpression uses this to tell
436: // division from a regex: a '/' right after a value is division. Non-ASCII is
437: // always an identifier char here (every JS operator is ASCII), so it counts as
438: // a value — otherwise `x = π / 2` would read the '/' as a regex.
439: bool isValueChar (char16_t c) {
440:   return c >= '0' && c <= '9' || c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c == '_' || c == '$' || c >= 128;
441: }
442: 
443: // Skips an initializer or default-value expression, returning the depth-0
444: // terminator (',' or ';', or an enclosing ')'/']'/'}' that the expression did
445: // not open) and leaving pos AT it. With `asi` set, a line break following a
446: // value also terminates, so the statement after an automatic semicolon is never
447: // read as another binding. Entry: pos AT the char before the expression (the
448: // '=' of an initializer, or the '[' of a computed key).
449: char16_t skipExpression (bool asi) {
450:   // Rides consumeToken (the single tokenizer) so the regex/keyword/import rules
451:   // match the main loop exactly. Ends at a ',' / ';' / enclosing closer at the
452:   // entry depth, or - with asi - a line break after a value. Entry: pos AT the
453:   // char before the expression (the '=' of an initializer or the '[' of a
454:   // computed key); that char is the previous token, so a leading '/' is a regex.
455:   uint32_t baseDepth = openTokenDepth;
456:   bool lastWasValue = false;
457:   lastTokenPos = pos;
458:   while (pos++ < end) {
459:     char16_t ch = *pos;
460:     if (isWsNotBr(ch))
461:       continue;
462:     if (openTokenDepth == baseDepth) {
463:       if (ch == ',' || ch == ';' || ch == ')' || ch == ']' || ch == '}')
464:         return ch;
465:       if (asi && lastWasValue && isBr(ch))
466:         return ch;
467:     }
468:     if (isBr(ch))
469:       continue;
470:     char16_t* before = lastTokenPos;
471:     consumeToken(ch);
472:     if (has_error)
473:       return '\0';
474:     if (lastTokenPos == before) {
475:       // a comment: a line comment can land on the ASI-terminating line break
476:       if (asi && openTokenDepth == baseDepth && lastWasValue && isBr(*pos))
477:         return *pos;
478:     }
479:     else {
480:       lastWasValue = ch == '/' ? !lastSlashWasDivision
481:                    : isValueChar(ch) || ch == ')' || ch == ']' || ch == '}' || ch == '\'' || ch == '"' || ch == '`';
482:     }
483:   }
484:   return '\0';
485: }
486: 
487: // pos AT a binding target: an identifier or a nested '{'/'[' destructuring
488: // pattern. Adds the bound name(s), then skips trailing whitespace/comments and
489: // returns the next significant char with pos AT it. pos is left unchanged when
490: // no target is present (malformed input or the end of a binding list).
491: char16_t readBindingTarget (char16_t ch) {
492:   if (ch == '{' || ch == '[') {
493:     readBindingPattern();
494:     pos++;
495:   } else {
496:     char16_t* nameStart = pos;
497:     readToWsOrPunctuator(ch);
498:     if (pos > nameStart)
499:       addExport(nameStart, pos, nameStart, pos);
500:   }
501:   return commentWhitespace(true);
502: }
503: 
504: // pos AT '{' or '['. Adds every identifier bound by the destructuring pattern,
505: // resolving aliases ({ a: b } adds b), defaults ({ a = 1 } adds a), rest
506: // (...rest adds rest) and arbitrary nesting. Leaves pos AT the matching closer.
507: void readBindingPattern () {
508:   bool isObject = *pos == '{';
509:   char16_t close = isObject ? '}' : ']';
510:   pos++;
511:   char16_t ch = commentWhitespace(true);
512:   while (ch != close && pos <= end) {
513:     // ...rest element
514:     if (ch == '.' && *(pos + 1) == '.' && *(pos + 2) == '.') {
515:       pos += 3;
516:       ch = commentWhitespace(true);
517:       ch = readBindingTarget(ch);
518:       continue;
519:     }
520:     if (isObject) {
521:       char16_t* keyStart = pos;
522:       char16_t* keyEnd = pos;
523:       if (ch == '[') {
524:         skipExpression(false); // computed key: pos AT matching ']'
525:         pos++;
526:         ch = commentWhitespace(true);
527:       } else if (isQuote(ch)) {
528:         stringLiteral(ch);
529:         pos++;
530:         ch = commentWhitespace(true);
531:       } else if (ch >= '0' && ch <= '9') {
532:         ch = *(++pos);
533:         while ((ch >= '0' && ch <= '9') || ch == '.' || ch == '_' ||
534:                ch == 'e' || ch == 'E' || ch == 'n' ||
535:                ch == 'x' || ch == 'X' || ch == 'b' || ch == 'B' || ch == 'o' || ch == 'O' ||
536:                (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F') ||
537:                ((ch == '+' || ch == '-') && (*(pos - 1) == 'e' || *(pos - 1) == 'E')))
538:           ch = *(++pos);
539:         ch = commentWhitespace(true);
540:       } else {
541:         readToWsOrPunctuator(ch);
542:         keyEnd = pos;
543:         ch = commentWhitespace(true);
544:       }
545:       // { key: target } binds target; shorthand { key } / { key = default }
546:       // binds the key. A computed ([expr]) or string key has no shorthand.
547:       if (ch == ':') {
548:         pos++;
549:         ch = commentWhitespace(true);
550:         ch = readBindingTarget(ch);
551:       } else if (keyEnd > keyStart) {
552:         addExport(keyStart, keyEnd, keyStart, keyEnd);
553:       }
554:     } else if (ch == ',') { // array elision
555:       pos++;
556:       ch = commentWhitespace(true);
557:       continue;
558:     } else {
559:       ch = readBindingTarget(ch);
560:     }
561:     if (ch == '=')
562:       ch = skipExpression(false); // default value
563:     if (ch == ',') {
564:       pos++;
565:       ch = commentWhitespace(true);
566:     } else {
567:       break;
568:     }
569:   }
570: }
