572: void tryParseExportStatement () {
573:   char16_t* sStartPos = pos;
574:   Export* prev_export_write_head = export_write_head;
575: 
576:   pos += 6;
577: 
578:   char16_t* curPos = pos;
579: 
580:   char16_t ch = commentWhitespace(true);
581: 
582:   if (pos == curPos && !isPunctuator(ch))
583:     return;
584: 
585: #ifndef LEXER_MIN
586:   // Only commit the statement start once this is a real export: skipExpression
587:   // re-enters here for an `export`-prefixed identifier (e.g. `exports`) in an
588:   // initializer, which would otherwise clobber the start for later bindings.
589:   export_statement_start = sStartPos;
590: #endif
