592:   if (ch == '{') {
593:     pos++;
594:     ch = commentWhitespace(true);
595:     while (true) {
596:       char16_t* startPos = pos;
597: 
598:       if (!isQuote(ch)) {
599:         ch = readToWsOrPunctuator(ch);
600:       }
601:       // export { "identifer" as } from
602:       // export { "@notid" as } from
603:       // export { "spa ce" as } from
604:       // export { " space" as } from
605:       // export { "space " as } from
606:       // export { "not~id" as } from
607:       // export { "%notid" as } from
608:       // export { "identifer" } from
609:       // export { "%notid" } from
610:       else {
611:         stringLiteral(ch);
612:         pos++;
613:       }
614: 
615:       char16_t* endPos = pos;
616:       commentWhitespace(true);
617:       ch = readExportAs(startPos, endPos);
618:       // ,
619:       if (ch == ',') {
620:         pos++;
621:         ch = commentWhitespace(true);
622:       }
623:       if (ch == '}')
624:         break;
625:       if (pos == startPos)
626:         return syntaxError();
627:       if (pos > end)
628:         return syntaxError();
629:     }
630: #ifndef LEXER_MIN
631:     hasModuleSyntax = true; // to handle "export {}"
632: #endif
633:     pos++;
634:     ch = commentWhitespace(true);
635:   }
636:   // export *
637:   // export * as X
638:   else if (ch == '*') {
639:     pos++;
640:     commentWhitespace(true);
641:     ch = readExportAs(pos, pos);
642:     ch = commentWhitespace(true);
643:   }
644:   else {
645:     facade = false;
646:     switch (ch) {
647:       // export default ...
648:       case 'd': {
649:         const char16_t* startPos = pos;
650:         pos += 7;
651:         ch = commentWhitespace(true);
652:         bool localName = false;
653:         switch (ch) {
654:           // export default async? function*? name? (){}
655:           case 'a':
656:             if (memcmp(pos + 1, &SYNC[0], 4 * 2) == 0 && isWsNotBr(*(pos + 5))) {
657:               pos += 5;
658:               ch = commentWhitespace(false);
659:             }
660:             else {
661:               break;
662:             }
663:           // fallthrough
664:           case 'f':
665:             if (memcmp(pos + 1, &UNCTION[0], 7 * 2) == 0 && (isBrOrWs(*(pos + 8)) || *(pos + 8) == '*' || *(pos + 8) == '(')) {
666:               pos += 8;
667:               ch = commentWhitespace(true);
668:               if (ch == '*') {
669:                 pos++;
670:                 ch = commentWhitespace(true);
671:               }
672:               if (ch == '(') {
673:                 break;
674:               }
675:               localName = true;
676:             }
677:             break;
678:           case 'c':
679:             // export default class name? {}
680:             if (memcmp(pos + 1, &LASS[0], 4 * 2) == 0 && (isBrOrWs(*(pos + 5)) || *(pos + 5) == '{')) {
681:               pos += 5;
682:               ch = commentWhitespace(true);
683:               if (ch == '{') {
684:                 break;
685:               }
686:               localName = true;
687:             }
688:             break;
689:         }
690:         if (localName) {
691:           const char16_t* localStartPos = pos;
692:           readToWsOrPunctuator(ch);
693:           if (pos > localStartPos) {
694:             addExport(startPos, startPos + 7, localStartPos, pos);
695:             pos--;
696:             return;
697:           }
698:         }
699:         addExport(startPos, startPos + 7, NULL, NULL);
700:         pos = (char16_t*)(startPos + 6);
701:         return;
702:       }
703:       // export async? function*? name () {
704:       case 'a':
705:         pos += 5;
706:         commentWhitespace(false);
707:       // fallthrough
708:       case 'f':
709:         pos += 8;
710:         ch = commentWhitespace(true);
711:         if (ch == '*') {
712:           pos++;
713:           ch = commentWhitespace(true);
714:         }
715:         const char16_t* startPos = pos;
716:         ch = readToWsOrPunctuator(ch);
717:         addExport(startPos, pos, startPos, pos);
718:         pos--;
719:         return;
720: 
721:       // export class name ...
722:       case 'c':
723:         if (memcmp(pos + 1, &LASS[0], 4 * 2) == 0 && isBrOrWsOrPunctuatorNotDot(*(pos + 5))) {
724:           pos += 5;
725:           ch = commentWhitespace(true);
726:           const char16_t* startPos = pos;
727:           ch = readToWsOrPunctuator(ch);
728:           addExport(startPos, pos, startPos, pos);
729:           pos--;
730:           return;
731:         }
732:         pos += 2;
733:       // fallthrough
734: 
735:       // export var/let/const binding (, binding)*  — each binding is an
736:       // identifier or a destructuring pattern, optionally `= initializer`.
737:       // Initializers and defaults are skipped expression-aware (see
738:       // skipExpression) so a comma inside them does not split the binding list,
739:       // and the list ends at ';', EOF or an ASI line break — never reading into
740:       // the following statement.
741:       case 'v':
742:       case 'l': {
743:         pos += 3;
744:         facade = false;
745:         ch = commentWhitespace(true);
746:         while (pos <= end) {
747:           char16_t* bindingStart = pos;
748:           ch = readBindingTarget(ch);
749:           if (pos == bindingStart)
750:             break;
751:           if (ch == '=')
752:             ch = skipExpression(true);
753:           if (ch != ',')
754:             break;
755:           pos++;
756:           ch = commentWhitespace(true);
757:         }
758:         pos--;
759:         return;
760:       }
761: 
762:       default:
763:         return;
764:     }
765:   }
766: 
767:   // from ...
768:   if (ch == 'f' && memcmp(pos + 1, &ROM[0], 3 * 2) == 0) {
769:     pos += 4;
770:     readImportString(sStartPos, commentWhitespace(true), false);
771: 
772:     // There were no local names.
773:     for (Export* exprt = prev_export_write_head == NULL ? first_export : prev_export_write_head->next; exprt != NULL; exprt = exprt->next) {
774:       exprt->local_start = exprt->local_end = NULL;
775:     }
776:   }
777:   else {
778:     pos--;
779:   }
780: }
