817: void readImportString (const char16_t* ss, char16_t ch, int phase_keyword) {
818:   const char16_t* startPos = pos + 1;
819:   if (ch == '\'') {
820:     stringLiteral(ch);
821:   }
822:   else if (ch == '"') {
823:     stringLiteral(ch);
824:   }
825:   else {
826:     syntaxError();
827:     return;
828:   }
829:   addImport(ss, startPos, pos, STANDARD_IMPORT);
830:   if (phase_keyword > 0) {
831:     import_write_head->import_ty = phase_keyword == 1 ? StaticSourcePhase : StaticDeferPhase;
832:   }
833:   pos++;
834:   ch = commentWhitespace(false);
835:   if (!(ch == 'w' && *(pos + 1) == 'i' && *(pos + 2) == 't' && *(pos + 3) == 'h')) {
836:     pos--;
837:     return;
838:   }
839:   char16_t* attrIndex = pos;
840:   pos += 4;
841:   ch = commentWhitespace(true);
842:   if (ch != '{') {
843:     pos = attrIndex;
844:     return;
845:   }
846:   const char16_t* attrStart = pos;
847: #ifndef LEXER_MIN
848:   Attribute* attr_write_head = NULL;
849:   Attribute* attr_write_head_last = NULL;
850: #endif
851:   do {
852:     pos++;
853:     ch = commentWhitespace(true);
854:     const char16_t* key_start;
855:     const char16_t* key_end;
856:     if (ch == '\'') {
857:       key_start = pos;
858:       stringLiteral(ch);
859:       key_end = pos + 1;
860:       pos++;
861:       ch = commentWhitespace(true);
862:     }
863:     else if (ch == '"') {
864:       key_start = pos;
865:       stringLiteral(ch);
866:       key_end = pos + 1;
867:       pos++;
868:       ch = commentWhitespace(true);
869:     }
870:     else {
871:       key_start = pos;
